import React, { useState, useEffect } from 'react';

/**
 * Hook to load real-time project data
 * Reads from .jose-madrid-status.json generated by analyzer
 */
export function useProjectStatus(projectPath) {
  const [status, setStatus] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdate, setLastUpdate] = useState(null);

  useEffect(() => {
    const loadStatus = async () => {
      try {
        setLoading(true);
        
        // In a real implementation, this would fetch from your server
        // For now, we'll use the file system API (Node.js environment)
        const fs = require('fs').promises;
        const path = require('path');
        
        const statusFile = path.join(projectPath, '.jose-madrid-status.json');
        const data = await fs.readFile(statusFile, 'utf8');
        const statusData = JSON.parse(data);
        
        setStatus(statusData);
        setLastUpdate(new Date(statusData.timestamp));
        setError(null);
      } catch (err) {
        setError(err.message);
        console.error('Failed to load project status:', err);
      } finally {
        setLoading(false);
      }
    };

    loadStatus();

    // Poll for updates every 30 seconds
    const interval = setInterval(loadStatus, 30000);

    return () => clearInterval(interval);
  }, [projectPath]);

  return { status, loading, error, lastUpdate };
}

/**
 * Hook to load project history
 */
export function useProjectHistory(projectPath) {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadHistory = async () => {
      try {
        const fs = require('fs').promises;
        const path = require('path');
        
        const historyFile = path.join(projectPath, '.jose-madrid-history.json');
        const data = await fs.readFile(historyFile, 'utf8');
        const historyData = JSON.parse(data);
        
        setHistory(historyData.runs || []);
      } catch (err) {
        console.error('Failed to load history:', err);
        setHistory([]);
      } finally {
        setLoading(false);
      }
    };

    loadHistory();
  }, [projectPath]);

  return { history, loading };
}

/**
 * Transform analyzer data to dashboard format
 */
export function transformAnalyzerData(analyzerStatus) {
  if (!analyzerStatus) return null;

  return {
    projectName: "Jose Madrid Salsa - E-commerce Website",
    client: "Jose Madrid Salsa Brands",
    developer: "Jlang.dev - Jordan Lang",
    startDate: "2024-11-01",
    targetLaunch: "2025-01-15",
    
    // Direct mapping from analyzer
    pages: analyzerStatus.pages.map(page => ({
      name: page.name,
      status: page.status,
      functionality: page.functionality,
      design: page.design,
      content: page.content,
      issues: page.issues,
      priority: determinePriority(page)
    })),
    
    technical: analyzerStatus.technical,
    
    blockers: analyzerStatus.criticalBlockers.map(blocker => ({
      id: Math.random().toString(36).substr(2, 9),
      issue: blocker.issue,
      severity: blocker.severity,
      page: blocker.page,
      discovered: blocker.discovered,
      status: blocker.status
    })),
    
    testing: Object.entries(analyzerStatus.testing).map(([category, data]) => ({
      category,
      completion: data.completion
    })),
    
    // Metrics
    launchReadiness: analyzerStatus.launchReadiness,
    runNumber: analyzerStatus.runNumber,
    timestamp: analyzerStatus.timestamp,
    
    // Claude Code work batch
    claudeCodeWorkBatch: analyzerStatus.claudeCodeWorkBatch
  };
}

function determinePriority(page) {
  const criticalPages = ['Cart', 'Checkout', 'Product', 'Products'];
  if (criticalPages.some(p => page.name.includes(p))) {
    return 'critical';
  }
  if (page.status === 'not-started') {
    return 'high';
  }
  return 'medium';
}

/**
 * WebSocket connection for real-time updates (optional)
 * Implement this if you want instant updates without polling
 */
export function useRealtimeUpdates(projectPath) {
  const [updates, setUpdates] = useState([]);

  useEffect(() => {
    // Watch for file changes using chokidar or fs.watch
    const fs = require('fs');
    const path = require('path');
    
    const statusFile = path.join(projectPath, '.jose-madrid-status.json');
    
    const watcher = fs.watch(statusFile, (eventType) => {
      if (eventType === 'change') {
        const data = fs.readFileSync(statusFile, 'utf8');
        const status = JSON.parse(data);
        setUpdates(prev => [...prev, {
          timestamp: new Date(),
          status
        }]);
      }
    });

    return () => watcher.close();
  }, [projectPath]);

  return updates;
}

